typedef struct Node { int value; struct Node *next; } Node;
Node *push(Node *head,int value){
    Node *node=malloc(sizeof(Node));
    node->value=value; node->next=head; return node;
}
Node *move_front(Node *head,int target){
    if(!head || head->value==target) return head;
    Node *prev=NULL,*cur=head;
    while(cur && cur->value!=target){ prev=cur; cur=cur->next; }
    if(cur){
        prev->next=cur->next;
        cur->next=head;
        head=cur;
    }
    return head;
}
int main(void){
    Node *head=NULL;
    for(int i=1;i<=5;i++) head=push(head,i);
    head=move_front(head,3);
    for(Node *p=head;p;p=p->next) printf("%d",p->value);
    return 0;
}

